ext('c12_geo_ch11',[
C("🌾","हरित क्रांति",["उन्नत बीज और उर्वरक","सिंचाई का विस्तार","पंजाब, हरियाणा, पश्चिमी उत्तर प्रदेश","गेहूँ और चावल की उपज बढ़ी"],"सन उन्नीस सौ साठ के दशक में भारत में हरित क्रांति आई। इसमें अधिक उपज देने वाले बीज, रासायनिक उर्वरक और सिंचाई का प्रयोग बढ़ाया गया। इसका सबसे ज़्यादा असर पंजाब, हरियाणा और पश्चिमी उत्तर प्रदेश में दिखा। गेहूँ और चावल का उत्पादन तेज़ी से बढ़ा और देश अनाज में आत्मनिर्भर बन गया।"),
C("⚠️","हरित क्रांति की समस्याएँ",["भूजल का अत्यधिक उपयोग","रसायनों से मिट्टी की हानि","क्षेत्रीय असमानता","छोटे किसानों को कम लाभ"],"हरित क्रांति से अनाज बढ़ा, पर कुछ समस्याएँ भी आईं। ज़्यादा सिंचाई से भूजल का स्तर नीचे गया। रासायनिक खादों के अधिक उपयोग से मिट्टी की गुणवत्ता घटी। यह क्रांति कुछ ही क्षेत्रों में सफल रही, जिससे क्षेत्रीय असमानता बढ़ी। छोटे किसानों को इसका कम लाभ मिल पाया।"),
C("🍵","बागान कृषि",["चाय, कॉफ़ी, रबड़","बड़े क्षेत्र में एक ही फ़सल","पूँजी और श्रम की अधिक ज़रूरत","निर्यात के लिए उत्पादन"],"बागान कृषि में चाय, कॉफ़ी, रबड़ और गन्ने जैसी फ़सलें बड़े पैमाने पर उगाई जाती हैं। इसमें एक ही फ़सल बड़े क्षेत्र में लगाई जाती है और पूँजी तथा श्रम की ज़्यादा ज़रूरत होती है। उत्पादन का बड़ा भाग निर्यात किया जाता है। असम की चाय और दक्षिण भारत की कॉफ़ी इसके अच्छे उदाहरण हैं।"),
C("🌱","जैविक कृषि और सतत खेती",["रसायन का कम प्रयोग","गोबर और कम्पोस्ट खाद","फ़सल चक्र का पालन","मिट्टी और पर्यावरण की रक्षा"],"जैविक कृषि में रासायनिक खाद और कीटनाशक की जगह गोबर की खाद, कम्पोस्ट और प्राकृतिक तरीके अपनाए जाते हैं। इसमें फ़सल चक्र का भी पालन होता है। इससे मिट्टी की उर्वरता बनी रहती है और पर्यावरण सुरक्षित रहता है। सिक्किम पूरी तरह जैविक राज्य बनने वाला पहला राज्य है।"),
C("🧑‍🌾","कृषि में सुधार के प्रयास",["भूमि सुधार","न्यूनतम समर्थन मूल्य","किसान क्रेडिट कार्ड","फ़सल बीमा योजना"],"किसानों की हालत सुधारने के लिए कई प्रयास हुए हैं। भूमि सुधार से ज़मींदारी खत्म हुई। न्यूनतम समर्थन मूल्य से किसानों को उपज का न्यूनतम दाम मिलता है। किसान क्रेडिट कार्ड से सस्ता कर्ज़ मिलता है। फ़सल बीमा योजना से प्राकृतिक आपदा में नुकसान की भरपाई होती है।"),
],5)
ext('c12_geo_ch12',[
C("🌊","जल की उपलब्धता",["पृथ्वी पर जल अधिक, मीठा कम","भारत में नदियों की संख्या अधिक","वर्षा का असमान वितरण","मौसम और क्षेत्र के अनुसार भिन्नता"],"पृथ्वी पर पानी बहुत है, पर उसका बहुत कम भाग मीठा और उपयोग के लायक है। भारत में नदियाँ बहुत हैं, पर वर्षा हर जगह समान नहीं होती। कहीं बाढ़ आती है तो कहीं सूखा पड़ता है। इसलिए जल की उपलब्धता क्षेत्र और मौसम के अनुसार बहुत बदलती रहती है।"),
C("🏜️","जल की कमी के कारण",["बढ़ती जनसंख्या","सिंचाई की माँग बढ़ना","उद्योग और शहरीकरण","पानी का दुरुपयोग"],"जनसंख्या बढ़ने से पानी की माँग तेज़ी से बढ़ी है। सिंचाई, उद्योग और शहरों में पानी की ज़्यादा ज़रूरत पड़ती है। साथ ही कई जगह पानी का दुरुपयोग होता है और प्रदूषण के कारण उपलब्ध पानी भी उपयोग लायक नहीं रहता। ये सब मिलकर जल संकट को गंभीर बनाते हैं।"),
C("🏞️","बहुउद्देशीय परियोजना",["सिंचाई","बिजली उत्पादन","बाढ़ नियंत्रण","मछली पालन और पर्यटन"],"बहुउद्देशीय परियोजना में एक बाँध से कई उद्देश्य पूरे होते हैं। इससे सिंचाई होती है और जलविद्युत बनती है। बाढ़ को नियंत्रित किया जाता है। साथ ही मछली पालन और पर्यटन को भी बढ़ावा मिलता है। भाखड़ा नांगल और हीराकुड परियोजनाएँ इसके प्रसिद्ध उदाहरण हैं।"),
C("☔","छत पर वर्षा जल संचयन",["छत से पाइप तक पानी","फ़िल्टर से सफ़ाई","टंकी या गड्ढे में संग्रह","भूजल का पुनर्भरण"],"वर्षा जल संचयन में छत पर गिरने वाला पानी पाइप से इकट्ठा करके टंकी में जमा किया जाता है। उसे फ़िल्टर से साफ़ करके उपयोग में लाया जाता है। इस पानी को ज़मीन के भीतर गड्ढों में डालकर भूजल का स्तर भी बढ़ाया जा सकता है। यह तरीका सस्ता और कारगर है।"),
C("🏜️","राजस्थान की परंपरागत विधियाँ",["टांका: घर का जल-कुंड","खडीन","बावड़ी","कम वर्षा में जीवन की व्यवस्था"],"राजस्थान जैसे सूखे इलाकों में लोगों ने पानी जमा करने की कई परंपरागत विधियाँ विकसित कीं। घरों में टांका नाम के भूमिगत कुंड बनते हैं, जिनमें वर्षा जल जमा किया जाता है। खडीन और बावड़ी जैसी रचनाएँ भी पानी रोककर रखती हैं। इनसे कम वर्षा वाले इलाकों में भी जीवन चलता है।"),
],5)
ext('c12_geo_ch13',[
C("⛏️","खनिजों का खनन",["भूमिगत खनन","खुला खनन","गहराई से निकालने का तरीका","सतह के पास सस्ता खनन"],"खनिजों को दो मुख्य तरीकों से निकाला जाता है। जब खनिज बहुत गहराई में होता है, तब भूमिगत खनन किया जाता है। जब खनिज सतह के पास हो, तो खुला खनन होता है, जो सस्ता और आसान है। खनन के साथ जंगल और भूमि को नुकसान भी होता है, इसलिए पर्यावरण की रक्षा ज़रूरी है।"),
C("🔩","धात्विक और अधात्विक खनिज",["लोहा, तांबा, बॉक्साइट","अभ्रक, चूना पत्थर","लौह और अलौह","ऊर्जा खनिज अलग श्रेणी"],"धात्विक खनिजों में धातु मिलती है, जैसे लोहा, तांबा और बॉक्साइट। अधात्विक खनिजों में धातु नहीं होती, जैसे अभ्रक और चूना पत्थर। धात्विक खनिज आगे लौह और अलौह में बँटते हैं। कोयला और पेट्रोलियम जैसे खनिज ऊर्जा देने वाले होते हैं, इसलिए उन्हें अलग श्रेणी में रखते हैं।"),
C("💡","पवन और सौर ऊर्जा",["सौर: सूर्य की ऊर्जा","पवन: हवा की गति","राजस्थान और गुजरात में सौर","तमिलनाडु में पवन ऊर्जा"],"सौर ऊर्जा सूर्य के प्रकाश से बनती है, और पवन ऊर्जा हवा की गति से। भारत में राजस्थान और गुजरात में सौर ऊर्जा की अच्छी संभावना है। तमिलनाडु पवन ऊर्जा में आगे है। ये ऊर्जा स्रोत नवीकरणीय हैं और प्रदूषण भी नहीं फैलाते, इसलिए भविष्य के लिए बहुत उपयोगी हैं।"),
C("♻️","ऊर्जा संरक्षण के उपाय",["बिजली का सोच-समझकर उपयोग","एलईडी बल्ब","सार्वजनिक परिवहन","नवीकरणीय स्रोत बढ़ाना"],"ऊर्जा संसाधन सीमित हैं, इसलिए उन्हें बचाना ज़रूरी है। घर में अनावश्यक बिजली बंद रखना, एलईडी बल्ब लगाना और सार्वजनिक परिवहन का उपयोग करना ऊर्जा बचाने के आसान तरीके हैं। साथ ही सौर और पवन जैसे नवीकरणीय स्रोतों का प्रयोग बढ़ाना चाहिए।"),
],5)
ext('c12_geo_ch14',[
C("🏔️","पहाड़ी क्षेत्र विकास कार्यक्रम",["पहाड़ों की विशेष समस्याएँ","बागवानी और पशुपालन","पर्यावरण की रक्षा","स्थानीय लोगों की भागीदारी"],"पहाड़ी क्षेत्रों में सड़क, बिजली और खेती की अलग समस्याएँ होती हैं। इसलिए इन क्षेत्रों के लिए पहाड़ी क्षेत्र विकास कार्यक्रम चलाया गया। इसमें बागवानी, पशुपालन और छोटे उद्योगों को बढ़ावा दिया गया। साथ ही यह ध्यान रखा गया कि पर्यावरण को नुकसान न हो और स्थानीय लोग भी योजनाओं में शामिल हों।"),
C("🌵","सूखा प्रवण क्षेत्र कार्यक्रम",["कम वर्षा वाले इलाके","जल संरक्षण पर ज़ोर","वृक्षारोपण","स्थानीय संसाधनों का उपयोग"],"जिन क्षेत्रों में वर्षा कम होती है और सूखा पड़ता रहता है, वहाँ सूखा प्रवण क्षेत्र कार्यक्रम शुरू किया गया। इसमें जल संरक्षण, वृक्षारोपण और चरागाह विकास पर ज़ोर दिया गया। स्थानीय संसाधनों का उपयोग करके लोगों की आजीविका सुधारने का प्रयास किया गया।"),
C("🌍","सतत पोषणीय विकास के तीन स्तंभ",["आर्थिक विकास","सामाजिक न्याय","पर्यावरण की सुरक्षा","आने वाली पीढ़ियों का ध्यान"],"सतत पोषणीय विकास का अर्थ है ऐसा विकास जो आज की ज़रूरतें पूरी करे और आने वाली पीढ़ियों की ज़रूरतों को नुकसान न पहुँचाए। इसके तीन स्तंभ हैं, आर्थिक विकास, सामाजिक न्याय और पर्यावरण की सुरक्षा। तीनों में संतुलन बनाए रखना ही इसका असली मकसद है।"),
C("🌊","इंदिरा गांधी नहर परियोजना की समस्याएँ",["राजस्थान का शुष्क इलाका","सिंचाई से पानी जमाव","मिट्टी में लवणता","फ़सल पद्धति में सुधार"],"इंदिरा गांधी नहर राजस्थान के सूखे इलाके में पानी पहुँचाने वाली बड़ी परियोजना है। इससे खेती का क्षेत्र बढ़ा, पर कुछ जगह पानी के जमाव और मिट्टी में लवणता की समस्या भी आई। इसलिए अब पानी की कम खपत वाली फ़सलें और सिंचाई की नई विधियाँ अपनाने पर ज़ोर दिया जा रहा है।"),
],5)
ext('c12_geo_ch15',[
C("🛣️","राष्ट्रीय राजमार्ग",["प्रमुख शहरों को जोड़ते","केंद्र सरकार की ज़िम्मेदारी","स्वर्णिम चतुर्भुज","सीमा क्षेत्रों तक पहुँच"],"राष्ट्रीय राजमार्ग देश के प्रमुख शहरों, बंदरगाहों और राज्यों को जोड़ते हैं। इनका निर्माण और रखरखाव केंद्र सरकार करती है। स्वर्णिम चतुर्भुज परियोजना ने दिल्ली, मुंबई, चेन्नई और कोलकाता को चार और छह लेन की सड़कों से जोड़ा। सीमावर्ती क्षेत्रों तक पहुँचने के लिए भी विशेष सड़कें बनाई गई हैं।"),
C("🚆","भारतीय रेल का महत्त्व",["सबसे बड़ा सार्वजनिक परिवहन","सस्ता और सुरक्षित","माल और यात्री दोनों","लंबी दूरी के लिए उपयोगी"],"भारतीय रेल दुनिया के बड़े रेल तंत्रों में से एक है। यह सस्ती और सुरक्षित सवारी देती है। इससे हर दिन करोड़ों यात्री और भारी मात्रा में माल ढोया जाता है। लंबी दूरी की यात्रा और भारी सामान ले जाने के लिए रेल सबसे उपयोगी साधन है।"),
C("✈️","हवाई परिवहन की विशेषताएँ",["सबसे तेज़ साधन","दुर्गम क्षेत्रों तक पहुँच","महँगा","आपदा में सहायता"],"हवाई परिवहन सबसे तेज़ साधन है। इससे पहाड़ी और दुर्गम इलाकों तक भी पहुँचा जा सकता है। यह महँगा ज़रूर है, पर बाढ़ या भूकंप जैसी आपदा में राहत पहुँचाने के लिए बहुत काम आता है। भारत में इंदिरा गांधी अंतरराष्ट्रीय हवाई अड्डा दिल्ली में है।"),
C("📡","संचार के आधुनिक साधन",["मोबाइल फ़ोन","इंटरनेट","उपग्रह संचार","डाक सेवा"],"आज संचार के साधन बहुत उन्नत हो गए हैं। मोबाइल फ़ोन और इंटरनेट से हम पल भर में दूर बैठे लोगों से बात कर सकते हैं। उपग्रह संचार से टेलीविज़न और मौसम की जानकारी मिलती है। डाक सेवा आज भी गाँव-गाँव में पत्र और पार्सल पहुँचाती है।"),
],5)
ext('c12_geo_ch16',[
C("🚢","बंदरगाहों की भूमिका",["व्यापार का प्रवेश द्वार","मुंबई, कांडला, विशाखापट्टनम","कोलकाता, चेन्नई, पारादीप","माल चढ़ाने-उतारने की सुविधा"],"अंतरराष्ट्रीय व्यापार का बड़ा भाग समुद्र के रास्ते होता है, इसलिए बंदरगाह बहुत महत्त्वपूर्ण हैं। भारत के प्रमुख बंदरगाहों में मुंबई, कांडला, विशाखापट्टनम, कोलकाता, चेन्नई और पारादीप शामिल हैं। ये बंदरगाह माल चढ़ाने, उतारने और भंडारण की सुविधा देते हैं।"),
C("💼","सूचना प्रौद्योगिकी का निर्यात",["सॉफ़्टवेयर सेवाएँ","बेंगलुरु, हैदराबाद, पुणे","विदेशी मुद्रा की कमाई","युवाओं के लिए रोज़गार"],"भारत सॉफ़्टवेयर और अन्य सूचना प्रौद्योगिकी सेवाओं का बड़ा निर्यातक है। बेंगलुरु, हैदराबाद और पुणे जैसे शहर इसके प्रमुख केंद्र हैं। इससे देश को बड़ी मात्रा में विदेशी मुद्रा मिलती है और युवाओं को रोज़गार भी। इसी कारण भारत की सेवा क्षेत्र की ताकत पूरी दुनिया में जानी जाती है।"),
C("🧭","भारत के प्रमुख व्यापारिक साझेदार",["अमेरिका","चीन","संयुक्त अरब अमीरात","अन्य एशियाई देश"],"भारत के सबसे बड़े व्यापारिक साझेदारों में अमेरिका, चीन और संयुक्त अरब अमीरात शामिल हैं। इनके साथ भारत बड़ी मात्रा में आयात-निर्यात करता है। भारत पेट्रोलियम और इलेक्ट्रॉनिक सामान आयात करता है, और रत्न-आभूषण, दवाएँ और इंजीनियरिंग सामान निर्यात करता है।"),
C("⚖️","व्यापार संतुलन और भुगतान",["निर्यात-आयात का अंतर","भारत में प्रायः व्यापार घाटा","तेल का आयात बड़ा कारण","सेवा निर्यात घाटा घटाता है"],"जब किसी देश का आयात उसके निर्यात से ज़्यादा हो, तो व्यापार घाटा होता है। भारत में प्रायः यही स्थिति रहती है, क्योंकि कच्चे तेल का आयात बहुत ज़्यादा है। सेवा निर्यात और विदेश से आने वाला धन इस घाटे को कुछ हद तक घटा देते हैं।"),
],5)
ext('c12_geo_ch17',[
C("🏭","जल प्रदूषण के स्रोत",["कारखानों का अपशिष्ट","घरेलू सीवेज","खेतों से रसायन","नदियों में गंदगी"],"जल प्रदूषण के मुख्य स्रोत कारखानों का रासायनिक अपशिष्ट, घरों और शहरों का गंदा पानी, और खेतों से बहकर आने वाले रसायन हैं। इन सबके नदियों में मिलने से जल दूषित हो जाता है। गंगा और यमुना जैसी नदियाँ इसी कारण प्रदूषण का शिकार हैं, और इससे स्वास्थ्य को खतरा होता है।"),
C("🧱","नगरीय अपशिष्ट",["घरों और बाज़ार का कचरा","अलग-अलग करके निपटारा","कम्पोस्ट और पुनर्चक्रण","लैंडफ़िल की समस्या"],"शहरों में घरों, दुकानों और उद्योगों से बहुत सारा कचरा निकलता है। अगर इसे ठीक से निपटाया न जाए तो बीमारियाँ फैलती हैं। इसलिए कचरे को गीला और सूखा अलग करके कम्पोस्ट और पुनर्चक्रण करना चाहिए। केवल कचरे के ढेर लगाने वाली लैंडफ़िल स्थायी समाधान नहीं है।"),
C("🏚️","गंदी बस्तियों की समस्याएँ",["भीड़ और कम जगह","साफ़ पानी की कमी","शौचालय और सफ़ाई का अभाव","स्वास्थ्य पर बुरा असर"],"बड़े शहरों में रोज़गार की तलाश में आए लोग प्रायः गंदी बस्तियों में रहते हैं। यहाँ बहुत भीड़ होती है और साफ़ पानी तथा शौचालय का अभाव रहता है। इससे बीमारियाँ तेज़ी से फैलती हैं। इनके सुधार के लिए आवास, पानी और स्वच्छता की योजनाएँ ज़रूरी हैं।"),
C("🌱","ग्रामीण समस्याएँ और समाधान",["कृषि पर निर्भरता","बेरोज़गारी","स्वास्थ्य और शिक्षा की कमी","स्थानीय रोज़गार के अवसर"],"गाँवों के लोग प्रायः खेती पर निर्भर होते हैं, और खेती में मौसम की अनिश्चितता रहती है। वहाँ बेरोज़गारी, स्वास्थ्य और शिक्षा की कमी भी बड़ी समस्याएँ हैं। समाधान के लिए गाँव में ही छोटे उद्योग और सेवा क्षेत्र के रोज़गार बढ़ाने होंगे, साथ ही स्कूल और स्वास्थ्य केंद्र मज़बूत करने होंगे।"),
],5)
